pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address admin, address caller, address _owner) public {
        // Ensure admin != caller and _owner != caller so the bug manifests distinct values
        vm.assume(admin != caller);
        vm.assume(_owner != caller);
        // The admin is the contract's deployer by default; we prank the setUp sender
        vm.startPrank(admin);
        c.setOwner(_owner);
        vm.stopPrank();
        // The reference sets owner = _owner; the bug sets owner = caller (here admin)
        assertTrue(c.owner() == _owner);
    }
}

