pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adminCaller, address _owner) public {
        // Restrict domain: adminCaller must be the original admin (msg.sender at deployment)
        // Since admin is set to payable(msg.sender) in C, we need to prank as that address.
        // We assume adminCaller is the deployer and prank accordingly.
        vm.assume(adminCaller != address(0));
        // The admin of C is the address that deployed it, which is this test contract's address.
        // So we need adminCaller to equal the test contract address.
        vm.assume(adminCaller == address(this));

        // Execute setOwner as admin
        vm.prank(adminCaller);
        c.setOwner(_owner);

        // Assertion: owner() must equal the provided _owner argument
        assertEq(c.owner(), _owner);
    }
}

