pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonAdmin) public {
        vm.assume(nonAdmin != address(c).call(abi.encodeWithSignature("admin()")));
        vm.assume(nonAdmin != address(this));
        address originalOwner = c.owner();
        vm.prank(nonAdmin);
        bool ok = false;
        try c.setOwner(address(0xdead)) { ok = true; } catch { ok = false; }
        assertTrue(ok == false ? c.owner() == originalOwner : true, "non-admin changed owner");
    }
}

