// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(c));
        vm.assume(caller != address(this));
        // record owner before call
        address prevOwner = c.owner();
        // call as caller
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool success) {
            if (success) {
                // if call succeeded, owner must have changed to newOwner
                assertTrue(c.owner() == newOwner);
            } else {
                // if call returned false, owner must be unchanged
                assertTrue(c.owner() == prevOwner);
            }
        } catch {
            // if call reverted, owner must be unchanged
            assertTrue(c.owner() == prevOwner);
        }
    }
}
